          { picto: '🚏', situacion: 'Someone greets you every morning at the bus stop, but you do not know anything else about them.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 2, pistas: ['Do you know anything else about this person? Without trust, there is no friendship.', 'Do you share an activity or a project? Here there is only a daily greeting.', ''], explicacion: 'This is an acquaintance: just a greeting, no conversation or trust.' },
          { picto: '🎨', situacion: 'At the painting class you help each other with materials, but each of you goes home separately.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 1, pistas: ['Does the relationship continue outside the workshop? If not, it is not a friendship yet.', '', 'Do you only say hello, or help each other with materials and share the activity?'], explicacion: 'This is a companion: you share the activity, not your free time.' },
          { picto: '🤗', situacion: 'This person stands up for you, listens to you, and you would do the same for them.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 0, pistas: ['', 'Do you only share an activity, or also stand up for each other and listen?', 'Do you only say hello, or is there support and listening both ways?'], explicacion: 'This is a friend: trust and support go both ways.' },
          { picto: '🧑‍🍳', situacion: "The canteen cook recognizes you and says hello, but you do not talk about anything else.", opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 2, pistas: ['Do you have trust and talk about your lives? Here there is only a greeting.', 'Do you share an activity or a job? Here there is only friendly everyday service.', ''], explicacion: 'This is an acquaintance: friendly treatment without real trust.' },
          { picto: '🧑‍🌾', situacion: 'You help together in the community garden every week, but you have never met outside it.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 1, pistas: ['Do you see each other outside the garden? If not, it is not a friendship yet.', '', 'Do you only say hello, or do you work together in the garden every week?'], explicacion: 'This is a companion: you share an activity, not your free time.' },
          { picto: '🎈', situacion: 'This person helped you through a hard time without asking for anything back, and you truly trust them.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 0, pistas: ['', 'Do you share only an activity, or also real help and trust?', 'Do you only say hello, or is there real help and trust?'], explicacion: 'This is a friend: selfless help and real trust.' },
          { picto: '🚉', situacion: 'You see this person every morning on the train and say hello, but you know nothing else about each other.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 2, pistas: ['Do you trust each other? Here you do not know anything else about each other.', 'Do you share an activity or a project? Here you only cross paths on the train.', ''], explicacion: 'This is an acquaintance: a daily greeting, no real conversation.' },
          { picto: '🎻', situacion: 'You rehearse together in the orchestra every week, but each of you goes home afterward.', opciones: ['Friend', 'Companion', 'Acquaintance'], correcta: 1, pistas: ['Does the relationship continue outside rehearsal? If not, it is not a friendship yet.', '', 'Do you only say hello, or do you rehearse together every week?'], explicacion: 'This is a companion: you share the activity, not your free time.' }
